def check_inclusion(s1, s2):
    k = len(s1)
    need, window = Counter(s1), Counter(s2[:k])
    if need == window:
        return True
    for i in range(k, len(s2)):
        window[s2[i]] += 1
        window[s2[i - k]] -= 1
        if window[s2[i - k]] == 0:
            del window[s2[i - k]]
        if window == need:
            return True
    return False

