    return b

def rob(nums):
    skip = take = 0               # best total if the previous house was skipped / taken
    for x in nums:
        skip, take = max(skip, take), skip + x
    return max(skip, take)

def coin_change(coins, amount):
    INF = amount + 1
    dp = [0] + [INF] * amount     # dp[a] = fewest coins for a
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

import bisect

def length_of_lis(nums):
    tails = []                    # tails[i] = smallest tail of an increasing run of length i+1
    for x in nums:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

def longest_common_subsequence(a, b):
    prev = [0] * (len(b) + 1)            # one row of the table at a time
    for ca in a:
        cur = [0]
        for j, cb in enumerate(b):
            cur.append(prev[j] + 1 if ca == cb else max(prev[j + 1], cur[j]))
        prev = cur
    return prev[-1]

def min_distance(a, b):
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            if ca == cb:
                cur.append(prev[j - 1])
            else:
                cur.append(1 + min(prev[j], cur[j - 1], prev[j - 1]))   # delete, insert, replace
        prev = cur
    return prev[-1]

def word_break(s, words):
    words = set(words)
    longest = max(map(len, words), default=0)
    ok = [True] + [False] * len(s)       # ok[i]: s[:i] can be split
    for i in range(1, len(s) + 1):
        for j in range(max(0, i - longest), i):
            if ok[j] and s[j:i] in words:
                ok[i] = True
                break
    return ok[-1]

def knapsack(items, capacity):
    dp = [0] * (capacity + 1)            # dp[c] = best value with capacity c
    for w, v in items:
        for c in range(capacity, w - 1, -1):   # backwards so each item is used once
            dp[c] = max(dp[c], dp[c - w] + v)
    return dp[capacity]

def merge(intervals):
    out = []
    for start, end in sorted(intervals):
        if out and start <= out[-1][1]:
            out[-1][1] = max(out[-1][1], end)
        else:
            out.append([start, end])
    return out

def can_jump(nums):
    reach = 0
    for i, x in enumerate(nums):
        if i > reach:
            return False
        reach = max(reach, i + x)
    return True

def can_complete_circuit(gas, cost):
    if sum(gas) < sum(cost):
        return -1
    start = tank = 0
    for i in range(len(gas)):
        tank += gas[i] - cost[i]
        if tank < 0:                  # nothing from start..i can be the answer
            start, tank = i + 1, 0
    return start

